package vn.covie.notifications.application; import java.util.*; import org.springframework.stereotype.Component; import vn.covie.notifications.model.NotificationType; import vn.covie.orders.persistence.OrderRepository; import vn.covie.outbox.application.*; import vn.covie.realtime.SseSignal; import vn.covie.reviews.persistence.ReviewRepository;
@Component public class ReviewNotificationHandler implements OutboxEventHandler {private final ReviewRepository reviews;private final OrderRepository orders;private final MerchantNotificationRecipientResolver recipients;private final NotificationService notifications;public ReviewNotificationHandler(ReviewRepository r,OrderRepository o,MerchantNotificationRecipientResolver m,NotificationService n){reviews=r;orders=o;recipients=m;notifications=n;}public boolean supports(String type){return "REVIEW_CREATED".equals(type);}public List<SseSignal> handle(OutboxEventContext event){var review=reviews.findById(event.aggregateId()).orElseThrow();var order=orders.findById(review.getOrderId()).orElseThrow();Map<String,Object> data=Map.of("reviewId",review.getId().toString(),"catalogItemId",review.getCatalogItemId().toString(),"orderId",review.getOrderId().toString(),"rating",review.getRating());List<SseSignal> signals=new ArrayList<>();for(UUID user:recipients.processorsForLocation(order.getMerchantProfileId(),order.getMerchantLocationId())){var result=notifications.createFromOutbox(event.eventId(),user,NotificationType.REVIEW_RECEIVED,"New review","A customer left a review.","REVIEW",review.getId(),data);if(result.created())signals.add(new SseSignal(user,"notification.created",Map.of("notificationId",result.notificationId().toString())));signals.add(new SseSignal(user,"review.created",Map.of("reviewId",review.getId().toString())));}return signals;}}
